**Concert Ticket UI**

### Overview

This is a simple user interface for buying tickets to a concert. It will allow users to select a concert, choose their seats, and purchase tickets.

### Code

```python
class Concert:
    def __init__(self, name, date, time, venue, price):
        self.name = name
        self.date = date
        self.time = time
        self.venue = venue
        self.price = price
        self.tickets = []

class Ticket:
    def __init__(self, seat_number, price):
        self.seat_number = seat_number
        self.price = price

class ConcertTicketUI:
    def __init__(self):
        self.concerts = [
            Concert("Rockstar", "2024-07-27", "20:00", "Madison Square Garden", 50),
            Concert("Popstar", "2024-07-28", "19:00", "Wembley Stadium", 60),
            Concert("Hip-Hop", "2024-07-29", "21:00", "Staples Center", 40)
        ]

    def display_concerts(self):
        print("Available Concerts:")
        for i, concert in enumerate(self.concerts):
            print(f"{i+1}. {concert.name} - {concert.date} - {concert.time} - {concert.venue} - ${concert.price}")

    def select_concert(self):
        self.display_concerts()
        choice = input("Enter the number of the concert you'd like to attend: ")
        try:
            choice = int(choice)
            if 1 <= choice <= len(self.concerts):
                return self.concerts[choice - 1]
            else:
                print("Invalid choice. Please try again.")
                return self.select_concert()
        except ValueError:
            print("Invalid input. Please enter a number.")
            return self.select_concert()

    def display_seats(self, concert):
        print(f"Available seats for {concert.name} on {concert.date} at {concert.venue}:")
        for i, seat in enumerate(concert.tickets):
            print(f"{i+1}. Seat {seat.seat_number} - ${seat.price}")

    def select_seat(self, concert):
        self.display_seats(concert)
        choice = input("Enter the number of the seat you'd like to select: ")
        try:
            choice = int(choice)
            if 1 <= choice <= len(concert.tickets):
                return concert.tickets[choice - 1]
            else:
                print("Invalid choice. Please try again.")
                return self.select_seat(concert)
        except ValueError:
            print("Invalid input. Please enter a number.")
            return self.select_seat(concert)

    def purchase_ticket(self):
        concert = self.select_concert()
        seat = self.select_seat(concert)
        print(f"Congratulations! You have purchased a ticket to {concert.name} on {concert.date} at {concert.venue} for seat {seat.seat_number} for ${seat.price}.")

def main():
    ui = ConcertTicketUI()
    while True:
        print("\nConcert Ticket UI")
        print("1. Buy tickets")
        print("2. Exit")
        choice = input("Enter your choice: ")
        if choice == "1":
            ui.purchase_ticket()
        elif choice == "2":
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

### Usage

1. Run the script.
2. Select the concert you'd like to attend by entering the corresponding number.
3. Select the seat you'd like to purchase by entering the corresponding number.
4. The script will display a confirmation message with the concert details and seat number.

